import sys


def main():
    data = sys.stdin.read().split('\n')
    n, k = map(int, data[0].split())
    toks = data[1].split()[:n] if len(data) > 1 else []
    count = {}
    for t in toks:
        count[t] = count.get(t, 0) + 1
    rows = sorted(count.items(), key=lambda x: (-x[1], x[0]))
    out = [f"{s} {c}" for s, c in rows[:k]]
    if out:
        print('\n'.join(out))


